                comps.append(comp)
    for comp in comps:
        ys=[y for y,_ in comp]; xs=[x for _,x in comp]
        R,C=min(ys),min(xs); h_=max(ys)-R+1; w_=max(xs)-C+1
        cands=[(r,c,I[r:r+h_,c:c+w_]) for r in range(H_-h_+1) for c in range(W_-w_+1)]
        src=None
        if O is not None:
            bests=[]
            for n,Vfn in Vtab.items():
                if n=='vh' and h_!=w_: continue
                for r in range(H_-h_+1):
                    for c in range(W_-w_+1):
                        A=Vfn(I[r:r+h_,c:c+w_])
                        dd=max(abs(R-r),abs(C-c))
                        if (A==O[R:R+h_,C:C+w_]).all(): bests.append((dd,r,c,n,A))
            if bests:
                chosen=min(bests,key=lambda b:(b[0],b[2],b[1]))
                src=(chosen[2],chosen[3],chosen[4])
