            src=min(cands,key=lambda t:(int((t[2]==6).sum()),abs(R-t[0])+abs(C-t[1]),t[0],t[1]))
        for rr in range(R,R+h_):
            for cc in range(C,C+w_):
                out[rr,cc]=src[2][rr-R][cc-C]
    return out
